from fractions import Fraction

def f(p, a, b):
    q_min = (b * p // (p - a)) + 1
    return Fraction(a, p) + Fraction(b, q_min)

a, b = 16, 9
for p in range(a + 1, a + 100):
    print(f"p={p}, S={f(p, a, b)}")

def f(n):
    a = 12 + n
    b = 13 - n
    return (a + 1) * (b * (a + 1) + 1)

for n in range(1, 13):
    print(f"n={n}, f(n)={f(n)}")
